local Utils = require(script.Parent.Parent.Utils)
local CollectionService = game:GetService("CollectionService")
local RunService = game:GetService("RunService")
local api = {}

local InputAdapter = require(script.Parent.InputAdapter)
local ViewModel = require(script.Parent.ViewModel)
local View = require(script.Parent.View)
local Model = require(script.Parent.Model)
local Defines = require(script.Parent.Parent.Defines)

local _vms = {}
local _globals = {}
local _vs = {}

local _inputAdaptable = false
local _bootstrapper = nil

function api:_getBootstrapper()
	if not _bootstrapper then
		local bootstrapper = {
			_children = {},
			_global = {
				_children = {},
				GetChildren = function(self)
					return self._children
				end,
			},
			_callbacks = {},
			AddModuleScript = function(self, module)
				if table.find(self._children, module) then
					warn(`[NezaUI] Module ${module.Name} already exists`)
					return
				end
				table.insert(self._children, module)
			end,
			AddGlobalModelScript = function(self, instance)
				table.insert(self._global._children, instance)
			end,
			GetChildren = function(self)
				return self._children
			end,
			FindFirstChild = function(self, name)
				if name == "_global" then
					return self._global
				end
			end,
			Start = function(self)
				api:_start(self, function()
					for i, v in pairs(self._callbacks) do
						pcall(v)
					end
				end)
			end,
			AddCallback = function(self, callback)
				table.insert(self._callbacks, callback)
			end,
		}
		bootstrapper.__index = bootstrapper
		bootstrapper._global.__index = bootstrapper._global
		_bootstrapper = bootstrapper
	end
	return _bootstrapper
end

-- load ui folder
function api:_init(folder)
	local ms = api:_initModels(folder)
	local vms = api:_initViewModels(folder)
	local vs = api:_initViews(folder)

	for i, v in pairs(vms) do
		local vm = require(v)
		if vm.Start and not vm._started then
			spawn(function()
				local suc, res = pcall(function()
					vm._started = true
					vm:Start()
				end)
				if not suc then
					warn(v)
					warn(res)
					warn(debug.traceback())
				end
			end)
		end
	end

	for i, v in pairs(vs) do
		local view = require(v)
		if view.Start and not view._started then
			spawn(function()
				local suc, res = pcall(function()
					view._started = true
					view:Start()
				end)
				if not suc then
					warn(v)
					warn(res)
					warn(debug.traceback())
				end
			end)
		end
	end

	api:_initCustomComponents()
end

function api:_initViewModels(folder)
	local all = {}
	for i, v in pairs(folder:GetChildren()) do
		if v:IsA("ModuleScript") and Utils.isModuleNotSpecial(v) then
			if _vms[v.Name] then
				warn(`[NezaUI] ViewModel ${v.Name} already exists`)
			end
			local suc, res = pcall(function()
				local vm = ViewModel.new(v)
				_vms[v.Name] = v
				table.insert(all, v)
			end)
			if not suc then
				warn(v)
				warn(res)
				warn(debug.traceback())
			end
		end
	end
	return all
end

function api:_initViews(folder)
	local all = {}

	local function initView(viewScript, parent)
		local suc, res = pcall(function()
			local view = View.new(viewScript, parent)
			table.insert(_vs, viewScript)
			table.insert(all, viewScript)
		end)
		if not suc then
			warn(viewScript)
			warn(res)
			warn(debug.traceback())
		end

		for _, v in pairs(viewScript:GetDescendants()) do
			if v:IsA("ModuleScript") then
				initView(v, viewScript)
			end
		end
	end

	for i, v in pairs(folder:GetChildren()) do
		if v:IsA("ModuleScript") then
			local viewScript = v:FindFirstChild("View")
			if not viewScript then
				continue
			end
			if viewScript:IsA("Folder") then
				for j, k in pairs(viewScript:GetChildren()) do
					if k:IsA("ModuleScript") then
						initView(k, nil)
					end
				end
			end
		end
	end

	if _inputAdaptable then
		api:_initInputs(folder, all)
	end

	return all
end

function api:_initInputs(folder, all)
	local inputs = InputAdapter:Init(folder)
	if inputs then
		for i, v in pairs(inputs) do
			table.insert(all, v)
		end
	end
end

function api:_initModels(folder)
	local all = {}
	local _commons = folder:FindFirstChild("_common")
	for i, vmScript in pairs(folder:GetChildren()) do
		if vmScript:IsA("ModuleScript") then
			local models = vmScript:FindFirstChild("Model")
			if models then
				if models:IsA("Folder") then
					if _commons then
						for i, v in pairs(_commons:GetChildren()) do
							if v:IsA("ModuleScript") and not models:FindFirstChild(v.Name) then
								local commonScript = v:Clone()
								commonScript.Parent = models
							end
						end
					end

					for j, k in pairs(models:GetChildren()) do
						if k:IsA("ModuleScript") then
							local suc, res = pcall(function()
								local model = Model.new(k)
								table.insert(all, k)
							end)
							if not suc then
								warn(k)
								warn(res)
								warn(debug.traceback())
							end
						end
					end
				end
			end
		end
	end

	-- init _global
	local _global = folder:FindFirstChild("_global")
	if _global then
		for i, v in pairs(_global:GetChildren()) do
			if v:IsA("ModuleScript") and not _globals[v.Name] then
				require(v)._global = v.Name
				local suc, res = pcall(function()
					local model = Model.new(v)
					_globals[v.Name] = v
					table.insert(all, v)
				end)
				if not suc then
					warn(res)
					warn(debug.traceback())
				end
			else
				warn(`[NezaUI] Model ${v.Name} already exists or not a ModuleScript`)
			end
		end
	end
	return all
end

function api:_initCustomComponents()
	local tagUIs = CollectionService:GetTagged("NezaComponent")
	for i, v in pairs(tagUIs) do
		local component = v:GetAttribute("__NezaComponent")
		if not component then
			continue
		end
		local suc, res = pcall(function()
			local componentLoader = require(script.Parent.Component)
			componentLoader.Get(v, component)
		end)
		if not suc then
			warn(v)
			warn(res)
			warn(debug.traceback())
		end
	end
end

function api:_start(folder, callback)
	spawn(function()
		local suc, err = pcall(function()
			api:_init(folder)
		end)
		if suc then
			if callback then
				callback()
			end
		else
			warn(err)
		end
	end)
end

function api:_getModel(modelName, vmName)
	if vmName then
		local vm = _vms[vmName]
		if not vm then
			return nil
		end
		local model = vm:FindFirstChild("Model")
		if not model then
			return nil
		end
		local modelScript = model:FindFirstChild(modelName)
		if not modelScript then
			return nil
		end
		return require(modelScript)
	else
		local global = _globals[modelName]
		if not global then
			return nil
		end
		return require(global)
	end
end

function api:_getViewModel(vmName)
	return require(_vms[vmName])
end

function api:_getViewModelScript(vmName)
	return _vms[vmName]
end

function api:_enableStudioDebugger()
	if RunService:IsStudio() and RunService:IsClient() then
		require(script.Parent.Parent.debugger):Init()
	end
end

function api:_getAllGlobalModels()
	return _globals
end

function api:_getAllViewModels()
	return _vms
end

local function getInstance(path, type)
	local ins = nil
	local segments = string.split(path, ".")
	for i, v in pairs(segments) do
		if i == 1 then
			ins = game[v]
		else
			ins = ins:WaitForChild(v)
		end
	end
	type = type or "Instance"
	return ins:IsA(type) and ins or nil
end

local function _boot(cfg)
	_inputAdaptable = cfg.InputAdaptable or false

	local starts = cfg.Starts or {}
	local startModules = cfg.StartModules or {}
	local callback = cfg.OnBootstraped
	local bootstrapper = api:_getBootstrapper()
	if callback then
		bootstrapper:AddCallback(callback)
	end

	for _, uipath in pairs(starts) do
		if typeof(uipath) == "string" then
			local folder = getInstance(uipath)
			if folder then
				for _, module in pairs(folder:GetChildren()) do
					if module:IsA("ModuleScript") then
						bootstrapper:AddModuleScript(module)
					end
				end
				local global = folder:FindFirstChild("_global")
				if global then
					for _, module in pairs(global:GetChildren()) do
						if module:IsA("ModuleScript") then
							bootstrapper:AddGlobalModelScript(module)
						end
					end
				end
			end
		end
	end

	for i, v in pairs(startModules) do
		local vmScript: Instance = getInstance(v)
		if vmScript and vmScript:IsA("ModuleScript") then
			bootstrapper:AddModuleScript(vmScript)
		elseif vmScript.Name == "_global" and vmScript:IsA("Folder") then
			for _, module in pairs(vmScript:GetChildren()) do
				if module:IsA("ModuleScript") then
					bootstrapper:AddGlobalModelScript(module)
				end
			end
		end
	end

	bootstrapper:Start()
end

local function _loadSprites(cfg)
	local spritesheets = cfg.SpriteSheets or {}
	local spriteLoader = require(script.Parent.Sprite.Loader)
	for i, v in pairs(spritesheets) do
		local folder: Instance = getInstance(v)
		if folder then
			if folder:IsA("Folder") then
				for i, v in pairs(folder:GetChildren()) do
					if v:IsA("ModuleScript") then
						spriteLoader.LoadModule(v)
					end
				end
			elseif folder:IsA("ModuleScript") then
				spriteLoader.LoadModule(folder)
			end
		end
	end
end

local function _loadComponents(cfg)
	local components = cfg.Components or {}
	local componentLoader = require(script.Parent.Component)
	for i, v in pairs(components) do
		local folder = getInstance(v, "Folder")
		if folder then
			for i, v in pairs(folder:GetChildren()) do
				if v:IsA("ModuleScript") then
					componentLoader.LoadComponent(v.Name, v)
				end
			end
		end
	end
end

local function _loadPrefabs(cfg)
	local prefabs = cfg.Prefabs or {}
	local prefabLoader = require(script.Parent.Prefab.Loader)
	for i, v in pairs(prefabs) do
		local folder = getInstance(v, "Folder")
		if folder then
			for i, v in pairs(folder:GetChildren()) do
				prefabLoader.LoadPrefab(v.Name, v)
			end
		end
	end
end

function api:_boot(cfg)
	assert(typeof(cfg) == "table", "[ Neza ] cfg must be a table")

	Model.Injection = cfg.Injection or nil
	Model.WuKongProvider = cfg.WuKongProvider or nil

	--#region Sprites
	_loadSprites(cfg)
	--#region

	--#region Components
	_loadComponents(cfg)
	--#region

	--#region Prefabs
	_loadPrefabs(cfg)
	--#region

	--#region Start
	_boot(cfg)
	--#endregion
end

function api:_instance(t: "View" | "ViewModel", ...)
	if typeof(t) == "string" then
		if t == "View" then
			return View.new(...) :: Defines.View
		end
	end
end

local bindablefunc: BindableFunction = script.Parent.Parent.BindableFunction
bindablefunc.OnInvoke = function(cmd, ...)
	if api[cmd] then
		return api[cmd](api, ...)
	end
end

return api
